fn put(o:&mut[u8],p:usize,x:f64){o[p..p+8].copy_from_slice(&x.to_le_bytes());}
fn gram(v:&[i64],c:usize,p:usize,part:usize,g:&mut[f64;9]){let n=c*p;for i in 0..c{for j in 0..c{let mut dot=0.0;for k in 0..p{dot+=(v[3+part*n+i*p+k] as f64/1000.0)*(v[3+part*n+j*p+k] as f64/1000.0);}g[i*c+j]=dot/n as f64;}}}
#[no_mangle]
pub unsafe extern "C" fn gramian(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<3||n>27{return -1}let a=std::slice::from_raw_parts(v,n);let(op,c,p)=(a[0],a[1],a[2]);if !(op==0||op==1)||!(1..=3).contains(&c)||!(1..=4).contains(&p)||n!=3+(c*p*(if op==1{2}else{1}))as usize{return -1}if a[3..].iter().any(|x|!(-1000..=1000).contains(x)){return -1}let(c,p)=(c as usize,p as usize);let count=if op==1{1}else{c*c};let bytes=count*8;if out.is_null()||cap<bytes{return -2}let(mut g1,mut g2)=([0.0;9],[0.0;9]);gram(a,c,p,0,&mut g1);let mut z=[0.0;9];if op==1{gram(a,c,p,1,&mut g2);for i in 0..c*c{let d=g1[i]-g2[i];z[0]+=d*d;}}else{z=g1;}let b=std::slice::from_raw_parts_mut(out,bytes);for i in 0..count{put(b,i*8,z[i]);}bytes as i64}
